senkei marching_line {
    action attack_top_unit {
    when true,
    do attack_unit(
        argmin unit in filter unit in allies.units { unit.lane == top }
            by unit.position then unit.slot_id,
        argmin target in filter target in enemies.visible_units {
            target.lane == top,
            target.hp > 0,
        } by target.hp then target.slot_id,
    ),
},
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when true,
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei core_pressure {
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when true,
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei intercept_visible {
    action intercept_top_unit {
    when true,
    do attack_unit(
        argmin unit in filter unit in allies.units { unit.lane == top }
            by unit.position then unit.slot_id,
        argmax target in filter target in enemies.visible_units {
            target.lane == top,
            target.hp > 0,
    } by target.position then target.slot_id,
    ),
},
    action intercept_mid_unit {
    when true,
    do attack_unit(
        argmin unit in filter unit in allies.units { unit.lane == mid }
            by unit.position then unit.slot_id,
        argmax target in filter target in enemies.visible_units {
            target.lane == mid,
            target.hp > 0,
    } by target.position then target.slot_id,
    ),
},
    action intercept_bot_unit {
    when true,
    do attack_unit(
        argmin unit in filter unit in allies.units { unit.lane == bot }
            by unit.position then unit.slot_id,
        argmax target in filter target in enemies.visible_units {
            target.lane == bot,
            target.hp > 0,
    } by target.position then target.slot_id,
    ),
},
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when true,
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei tower_pressure {
    state top_tower_stance {
    any ally in allies.units {
        ally.lane == top,
        ally.position >= 13,
        ally.position <= 17,
    },
    any tower in enemies.visible_towers {
        tower.lane == top,
        tower.hp > 0,
    },
},
    action attack_top_tower {
    when true,
    do attack_tower(
        argmax actor in filter unit in allies.units {
            unit.lane == top,
            unit.position >= 13,
            unit.position <= 17,
        } by actor.position then actor.slot_id,
        argmin target in filter tower in enemies.visible_towers {
            tower.lane == top,
            tower.hp > 0,
        } by target.hp then target.id,
    ),
},
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when not { top_tower_stance, },
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei hold_under_pressure {
    state wounded {
    self.core.hp < 300,
},
    action withdraw {
    when wounded,
    do move_backward(argmin unit in allies.units by unit.position then unit.slot_id),
},
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when not { wounded, },
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei medic_support {
    state ally_injured {
    any ally in allies.units {
        ally.lane == top,
        ally.hp < ally.max_hp,
    },
},
    action support_top {
    when ally_injured,
    do use_ability(
        argmin medic in filter unit in allies.units {
            unit.lane == top,
            unit.unit_class == medic,
        } by medic.hp then medic.slot_id,
        argmin ally in filter unit in allies.units {
            unit.lane == top,
            unit.hp < unit.max_hp,
        } by ally.hp then ally.slot_id,
    ),
},
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when true,
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}

senkei deploy_reserve {
    action deploy_next {
        when match.tick >= 4,
        do deploy(
            argmin barracks in allies.barracks by barracks.resources then barracks.id,
            argmin reserve in filter reserve in allies.reserves {
                reserve.available_tick <= match.tick,
            } by reserve.available_tick then reserve.slot_id,
            mid,
        ),
    },
    action strike_core {
    when true,
    do attack_core(
        argmin unit in allies.units by unit.position then unit.slot_id,
        argmin core in enemies.visible_cores by core.hp then core.id,
    ),
},
    action advance_line {
    when true,
    do move_forward(argmin unit in allies.units by unit.position then unit.slot_id),
},
}
